import React, { useEffect, useRef, memo } from 'react';
import './NiftyChart.css';

const NiftyChart = () => {
  const containerRef = useRef();

  useEffect(() => {
    // Check if the script is already there to prevent React StrictMode duplicates
    if (containerRef.current && !containerRef.current.querySelector('script')) {

        const script = document.createElement('script');
        script.src = 'https://s3.tradingview.com/external-embedding/embed-widget-mini-symbol-overview.js';
        script.type = 'text/javascript';
        script.async = true;

        script.innerHTML = JSON.stringify({
          "symbol": "BSE:SENSEX", // CHANGED: Now pulling the BSE Sensex data
          "width": "100%",
          "height": "350",
          "locale": "en_IN",
          "dateRange": "1M",
          "colorTheme": "light",
          "trendLineColor": "#14C4B5",
          "underLineColor": "rgba(20, 196, 181, 0.3)",
          "underLineBottomColor": "rgba(20, 196, 181, 0)",
          "isTransparent": false,
          "autosize": false,
          "largeChartUrl": ""
        });

        containerRef.current.appendChild(script);
    }
  }, []);

  return (
    <div className="chart-widget-block">
      {/* CHANGED: Updated the title to match the new data */}
      <h3 className="chart-title">India Market: BSE SENSEX</h3>

      <div className="tradingview-widget-container" ref={containerRef}>
        <div className="tradingview-widget-container__widget"></div>
      </div>

    </div>
  );
};

export default memo(NiftyChart);
